// rsi's synthetic program errors (generated by bin/rsi synthetic from errors): do not edit
use std::error::Error;
use std::fmt;
use std::hint::black_box as bb;
use std::num::ParseIntError;
#[derive(Debug)]
enum AppError { Parse(ParseIntError), Neg(i64), Io(String) }
impl fmt::Display for AppError { fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result { match self { AppError::Parse(e) => write!(f, "parse: {}", e), AppError::Neg(n) => write!(f, "negative: {}", n), AppError::Io(s) => write!(f, "io: {}", s) } } }
impl Error for AppError { fn source(&self) -> Option<&(dyn Error + 'static)> { match self { AppError::Parse(e) => Some(e), _ => None } } }
impl From<ParseIntError> for AppError { fn from(e: ParseIntError) -> Self { AppError::Parse(e) } }
fn parse(s: &str) -> Result<i64, AppError> { let n: i64 = s.trim().parse()?; if n < 0 { Err(AppError::Neg(n)) } else { Ok(n) } }
fn sum_all(xs: &[&str]) -> Result<i64, AppError> { let mut t = 0; for x in xs { t += parse(x)?; } Ok(t) }
fn dynerr(s: &str) -> Result<u8, Box<dyn Error>> { let n = parse(s)?; if n > 255 { return Err("too big".into()); } Ok(n as u8) }
fn opt(v: &[i32]) -> Option<i32> { let a = v.get(0)?; let b = v.get(1)?; a.checked_add(*b) }
fn main() {
    for s in ["42", " 7 ", "-3", "abc", "", "99999999999999999999", "+5"] { match parse(bb(s)) { Ok(n) => println!("ok {}", n), Err(e) => println!("err {} / {:?} / source {}", e, e, e.source().is_some()) } }
    println!("{:?}", sum_all(&["1", "2", "3"]).map_err(|e| e.to_string()));
    println!("{:?}", sum_all(&["1", "x"]).map_err(|e| e.to_string()));
    for s in ["200", "300", "-1", "q"] { match dynerr(s) { Ok(n) => println!("{}", n), Err(e) => println!("dyn: {}", e) } }
    println!("{:?} {:?} {:?}", opt(&[1, 2]), opt(&[1]), opt(&[i32::MAX, 1]));
    let r: Result<u8, _> = "256".parse::<u8>(); println!("{:?}", r);
    let r: Result<i8, _> = "-129".parse::<i8>(); println!("{:?}", r);
    println!("{:?} {:?}", "".parse::<u8>(), "1.5".parse::<f64>());
    println!("{:?} {:?}", "tru".parse::<bool>(), "true".parse::<bool>());
    let results: Vec<Result<i32, String>> = vec![Ok(1), Err("bad".into()), Ok(3)];
    let (oks, errs): (Vec<_>, Vec<_>) = results.into_iter().partition(|r| r.is_ok());
    println!("{} {}", oks.len(), errs.len());
    println!("{:?}", Some(3).ok_or("none").and_then(|x: i32| x.checked_sub(5).ok_or("under")));
    println!("{:?} {:?}", Some(4).filter(|x| x % 2 == 1), Some(2).xor(None::<i32>));
    println!("{} {}", Err::<i32, &str>("e").unwrap_or_default(), Ok::<i32, &str>(5).map_or(0, |x| x * 2));
    let e: Box<dyn Error + Send + Sync> = From::from("boxed message");
    println!("{} {:?}", e, e.to_string());
    println!("{}", AppError::Io("disk".into()));
}
